import lexMark from './assets/lex-mark.svg';
import lexMarkDark from './assets/lex-mark-dark.svg';
import MetalPromptBar, {type PromptSelection} from './components/ui/metal-prompt-bar';
import {AILoader} from './components/ui/ai-loader';
import {assistantPresentation} from './assistant-presentation';
import Avatar from './components/BrandAvatar';
import MatterBento from './components/ui/interactive-tech-stack-bento-grid-with-hover-effects';
import {version as appVersion} from '../package.json';
import AppCover from './components/AppCover';
import PublicLibrary from './PublicLibrary';
import { lazy, Suspense, useEffect, useRef, useState, type ReactNode } from 'react';
import { BookOpen, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, ClipboardList, Download, FileText, FolderOpen, Home, LayoutDashboard, Library, LoaderCircle, LockKeyhole, MessageSquare, Monitor, Moon, Plus, Search, Settings, ShieldCheck, Sparkles, Sun, Upload, X, PanelLeftClose, PanelLeftOpen, PanelRight, Copy } from 'lucide-react';
import CommandPalette, { type CommandItem } from './CommandPalette';
import DocumentText from './DocumentText';
import DocumentLibrary from './DocumentLibrary';
import MatterOverview from './MatterOverview';
import PendingView from './PendingView';
import AgentActionsView from './AgentActionsView';
import ConflictCheckView from './ConflictCheckView';
import ChecklistView from './ChecklistView';
import TrainingView from './TrainingView';
import SourcesView from './SourcesView';
import { analyze, api, downloadFile, emptyState, fileBase64, type DocumentRecord, type Answer, type AppState, type EngineStatus, type Feedback, type Matter, type Proposal, type Source } from './api';

const Dashboard = lazy(()=>import('./components/ui/app-1'));

type Page = 'drafts' | 'dashboard' | 'home' | 'workspace' | 'matters' | 'documents' | 'research' | 'skills' | 'knowledge' | 'settings' | 'sources' | 'dossier' | 'training' | 'library' | 'pending' | 'agent-actions' | 'conflicts' | 'checklist';
type Appearance = 'auto' | 'light' | 'dark';
const appearanceLabels: Record<Appearance,string> = {auto:'Automático',light:'Claro',dark:'Oscuro'};
function readAppearance(): Appearance {
  try { const saved=window.localStorage.getItem('lex-ai.appearance'); return saved==='light'||saved==='dark'||saved==='auto'?saved:'auto'; }
  catch { return 'auto'; }
}
function applyAppearance(value: Appearance) {
  if (value==='auto') document.documentElement.removeAttribute('data-theme');
  else document.documentElement.dataset.theme=value;
}
const pages: {id: Page; label: string; icon: typeof Home}[] = [
  {id:'workspace',label:'Asistente',icon:MessageSquare},{id:'matters',label:'Asuntos',icon:FolderOpen},{id:'drafts',label:'Escritos',icon:FileText},
  {id:'library',label:'Biblioteca federal',icon:BookOpen},{id:'conflicts',label:'Conflictos',icon:ShieldCheck},{id:'checklist',label:'Checklist',icon:ClipboardList},{id:'pending',label:'Pendientes',icon:CalendarDays},{id:'agent-actions',label:'Acciones propuestas',icon:ShieldCheck},
  {id:'dashboard',label:'Panel',icon:LayoutDashboard},{id:'home',label:'Inicio',icon:Home},{id:'training',label:'Calidad del asistente',icon:Sparkles},{id:'settings',label:'Configuración',icon:Settings},
  {id:'documents',label:'Documentos',icon:FileText},{id:'research',label:'Investigación',icon:Search},{id:'skills',label:'Habilidades',icon:Sparkles},{id:'sources',label:'Fuentes públicas',icon:BookOpen},{id:'knowledge',label:'Conocimiento',icon:Library}
];
const navigationGroups: {label: string; ids: Page[]}[] = [
  {label:'Trabajo',ids:['workspace','matters','drafts']},
  {label:'Herramientas jurídicas',ids:['library','conflicts','checklist','pending','agent-actions']},
  {label:'Sistema',ids:['dashboard','home','training','settings']}
];
const practiceOptions = ['Civil','Mercantil','Corporativo','Laboral','Fiscal','Administrativo','Constitucional','Litigio','Comercio internacional','Propiedad intelectual','Cumplimiento'];
const jurisdictionLabel = (value?: string) => value === 'MX-CMX' ? 'Ciudad de México' : value === 'MX-FED' ? 'Federal' : value || 'Sin jurisdicción';
const dateLabel = (value?: string) => value && !Number.isNaN(Date.parse(value)) ? new Intl.DateTimeFormat('es-MX',{dateStyle:'medium'}).format(new Date(/^\d{4}-\d{2}-\d{2}$/.test(value) ? `${value}T12:00:00` : value)) : 'Sin fecha';
const feedbackLabels: Record<string,string> = {accepted:'Aceptada',rejected:'Rechazada',corrected:'Corregida','citation-error':'Cita incorrecta'};
const proposalLabels: Record<string,string> = {proposed:'Inactiva',active:'Aprobada y activa',superseded:'Sustituida','rolled-back':'Revertida'};

function Empty({icon: Icon = FolderOpen, title, children, action}: {icon?: typeof Home; title: string; children?: ReactNode; action?: ReactNode}) {
  return <div className="empty-state"><Icon size={30} strokeWidth={1.3}/><h3>{title}</h3>{children && <p>{children}</p>}{action}</div>;
}
function Badge({children, tone='neutral'}: {children:ReactNode; tone?:string}) { return <span className={`badge ${tone}`}>{children}</span>; }
function OfficialSource({source, compact=false}: {source:Source; compact?:boolean}) {
  const official = Boolean(source.url);
  const url = source.url && /^https:\/\//i.test(source.url) ? source.url : undefined;
  return <article className={`source-card citation-seal ${compact ? 'compact' : ''}`} tabIndex={-1} id={`source-${source.id || source.sourceId}`}>
    <div className="source-label"><span className="source-seal-mark" aria-label="Pasaje fuente">§</span><Badge tone={official?'blue':'bronze'}>{official?<BookOpen size={12}/>:<FileText size={12}/>} {official?'Fuente oficial':'Documento del asunto'}</Badge>{source.article && <span>{/^art/i.test(source.article)?source.article:`Art. ${source.article}`}</span>}</div>
    <h3>{source.title || source.name || source.id || source.sourceId}</h3>
    {source.quote ? <blockquote>{source.quote}</blockquote> : source.text && !compact ? <p className="excerpt">{source.text}</p> : null}
    <div className="source-meta">{source.authority && <span>{source.authority}</span>}{source.jurisdiction && <span>{jurisdictionLabel(source.jurisdiction)}</span>}{source.version && <span>Versión: {source.version}</span>}{source.retrievedAt && <span>Consulta: {dateLabel(source.retrievedAt)}</span>}</div>
    {official && <><p className="source-warning">Instantánea documental. Vigencia y aplicabilidad por revisar.</p>{url && <a href={url} target="_blank" rel="noopener noreferrer">Consultar fuente original <ChevronRight size={13}/></a>}</>}
  </article>;
}

export default function App() {
  const [appearance,setAppearance] = useState<Appearance>(()=>{const value=readAppearance();applyAppearance(value);return value;});
  const [data,setData] = useState<AppState>(emptyState);
  const [engine,setEngine] = useState<EngineStatus>({state:'stopped'});
  const [page,setPage] = useState<Page>('workspace');
  const [dashboardScope,setDashboardScope] = useState('all');
  const [commandOpen,setCommandOpen]=useState(false);
  const commandOrigin=useRef<HTMLElement|null>(null);
  function openCommands(){commandOrigin.current=document.activeElement instanceof HTMLElement?document.activeElement:null;setCommandOpen(true);}
  useEffect(()=>{if(commandOpen||!commandOrigin.current)return;const origin=commandOrigin.current;commandOrigin.current=null;const frame=requestAnimationFrame(()=>{if(origin.isConnected&&!origin.closest('[inert]'))origin.focus();});return()=>cancelAnimationFrame(frame);},[commandOpen]);
  const [sidebarCollapsed,setSidebarCollapsed]=useState(false);
  const [mobileNavOpen,setMobileNavOpen]=useState(false);
  const [narrowViewport,setNarrowViewport]=useState(()=>window.innerWidth<=768);
  const [openNavigationGroups,setOpenNavigationGroups]=useState<Record<string,boolean>>({Trabajo:true,'Herramientas jurídicas':true,Sistema:true});
  const [railOpen,setRailOpen]=useState(false);
  const [railTab,setRailTab]=useState<'sources'|'outputs'>('sources');
  const [compactRail,setCompactRail]=useState(()=>window.innerWidth<1024);
  const citationFocus=useRef<string|null>(null);
  const [matterId,setMatterId] = useState('');
  const [loading,setLoading] = useState(true);
  const [busy,setBusy] = useState('');
  const [error,setError] = useState('');
  const [notice,setNotice] = useState('');
  const [showMatter,setShowMatter] = useState(false);
  const [viewer,setViewer] = useState<{name:string;text:string}|null>(null);
  const [question,setQuestion] = useState('');
  const promptSelection=useRef<PromptSelection|null>(null);
  const [skillId,setSkillId] = useState('legal-researcher');
  const [stream,setStream] = useState('');
  const [generating,setGenerating] = useState(false);
  const [selectedAnswer,setSelectedAnswer] = useState('');
  const streamController = useRef<AbortController|null>(null);
  const streamText = useRef('');
  const streamFrame = useRef<number|null>(null);
  const currentMatter = useRef(matterId);
  currentMatter.current = matterId;
  const matter = data.matters.find(item=>item.id===matterId);
  const documents = data.documents.filter(item=>item.matterId===matterId);
  const answers = data.answers.filter(item=>item.matterId===matterId);
  const activeAnswer = answers.find(item=>item.id===selectedAnswer) || answers.at(-1);
  const {state,label:assistantLabel,message:assistantMessage} = assistantPresentation(engine);
  const engineBusy = ['starting','downloading','verifying'].includes(state);
  useEffect(()=>{applyAppearance(appearance);try{localStorage.setItem('lex-ai.appearance',appearance);}catch{/* Storage is optional; the current session still renders correctly. */}},[appearance]);
  useEffect(()=>{const resize=()=>{setCompactRail(window.innerWidth<1024);setNarrowViewport(window.innerWidth<=768);if(window.innerWidth>768)setMobileNavOpen(false);};window.addEventListener('resize',resize);return()=>window.removeEventListener('resize',resize);},[]);
  useEffect(()=>{if(!compactRail||!railOpen||page!=='workspace')return;const frame=requestAnimationFrame(()=>{if(!citationFocus.current)document.querySelector<HTMLButtonElement>('#context-panel .icon-button')?.focus();});return()=>cancelAnimationFrame(frame);},[compactRail,railOpen,page]);
  useEffect(()=>{function shortcuts(event:KeyboardEvent){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(commandOpen)setCommandOpen(false);else openCommands();}if((event.metaKey||event.ctrlKey)&&event.key==='.'&&page==='workspace'&&activeAnswer){event.preventDefault();setRailOpen(open=>!open);}if((event.metaKey||event.ctrlKey)&&event.key===','){event.preventDefault();setPage('settings');}if(event.metaKey&&event.ctrlKey&&event.key.toLowerCase()==='s'){event.preventDefault();setSidebarCollapsed(value=>!value);}if(event.key==='Escape'&&railOpen&&!event.defaultPrevented&&!commandOpen&&!document.querySelector('dialog[open]')){setRailOpen(false);document.querySelector<HTMLButtonElement>('.rail-toggle')?.focus();}}window.addEventListener('keydown',shortcuts);return()=>window.removeEventListener('keydown',shortcuts);},[page,activeAnswer,railOpen,commandOpen]);
  useEffect(()=>{if(!railOpen||railTab!=='sources'||!citationFocus.current)return;const frame=requestAnimationFrame(()=>{const element=document.getElementById(`source-${citationFocus.current}`);element?.scrollIntoView({block:'nearest'});element?.focus({preventScroll:true});citationFocus.current=null;});return()=>cancelAnimationFrame(frame);},[railOpen,railTab,selectedAnswer]);
  function showCitation(id:string){citationFocus.current=id;setRailTab('sources');setRailOpen(true);requestAnimationFrame(()=>{const element=document.getElementById(`source-${id}`);element?.scrollIntoView({block:'nearest'});element?.focus({preventScroll:true});});}

  const pendingCount = data.tasks.filter(task=>task.matterId===matterId && task.status!=='completed').length;
  function navigateTo(id:Page) { setPage(id);setError('');setNotice('');if(narrowViewport)setMobileNavOpen(false); }


  async function refresh() { const next = await api<AppState>('state'); setData({...emptyState,...next}); return next; }
  async function load() {
    setError(''); setLoading(true);
    try {
      const [next,status] = await Promise.all([api<AppState>('state'),api<EngineStatus>('engine.status')]);
      setData({...emptyState,...next}); setEngine(status); setMatterId(previous=>previous || next.matters[0]?.id || '');
    } catch(e) { setError(e instanceof Error?e.message:'No se pudo abrir el espacio local.'); }
    finally {setLoading(false);}
  }
  useEffect(()=> {void load(); return ()=>{streamController.current?.abort();if(streamFrame.current) cancelAnimationFrame(streamFrame.current);};},[]);
  useEffect(()=> {
    if(!engineBusy) return;
    const timer=setInterval(()=>{void api<EngineStatus>('engine.status').then(setEngine).catch(()=>setEngine({state:'error',message:'Se perdió la conexión con el motor local.'}));},2000);
    return ()=>clearInterval(timer);
  },[engineBusy]);

  async function perform(label:string, task:()=>Promise<void>) {
    setBusy(label);setError('');setNotice('');
    try {await task();} catch(e) {setError(e instanceof Error?e.message:'No se pudo completar la operación.');}
    finally {setBusy('');}
  }
  function chooseMatter(id:string) {
    streamController.current?.abort();if(streamFrame.current!==null){cancelAnimationFrame(streamFrame.current);streamFrame.current=null;}streamText.current='';setGenerating(false);setStream('');setQuestion('');setSelectedAnswer('');setViewer(null);setRailOpen(false);setMatterId(id);
  }
  async function openDocument(doc:DocumentRecord) { const scope=doc.matterId; await perform('view',async()=>{const result=await api<{text:string}>('document.text',{documentId:doc.id,matterId:scope});if(currentMatter.current===scope)setViewer({name:doc.name,text:result.text});}); }
  function askAboutDocument(doc:DocumentRecord){setQuestion(`Sobre el documento «${doc.name}»: `);setPage('workspace');setNotice('La consulta puede recuperar evidencia de todos los documentos del asunto activo.');requestAnimationFrame(()=>document.getElementById('question')?.focus());}
  const commands:CommandItem[]=[...pages.map(item=>({id:`nav-${item.id}`,title:item.label,detail:'Abrir sección',group:navigationGroups.find(group=>group.ids.includes(item.id))?.label || 'Más vistas',icon:item.icon,run:()=>navigateTo(item.id)})),{id:'new-matter',title:'Crear nuevo asunto',detail:'Organizar un expediente privado',group:'Acciones',icon:Plus,run:()=>setShowMatter(true)},...(matter?[{id:'dossier',title:'Ver expediente activo',detail:matter.title,group:'Acciones',icon:FolderOpen,run:()=>setPage('dossier')},...documents.map(doc=>({id:doc.id,title:doc.name,detail:'Leer documento del asunto',group:'Documentos',icon:FileText,run:()=>void openDocument(doc)})),...answers.map(answer=>({id:answer.id,title:answer.question||'Análisis guardado',detail:dateLabel(answer.createdAt),group:'Consultas',icon:MessageSquare,run:()=>{setSelectedAnswer(answer.id);setPage('workspace');}}))]:[])];
  async function importFile(file:File) {
    if(!matterId) return;
    await perform('import',async()=>{await api('document.import',{matterId,name:file.name,base64:await fileBase64(file)});await refresh();setNotice(`«${file.name}» se importó y se indexó en este asunto.`);});
  }
  async function ask(text:string) {
    if(text.trim().length<3 || text.length>4000 || !matterId || generating || state!=='ready' || (!documents.length&&skillId!=='legal-researcher') || busy) return;
    const id=matterId; const controller=new AbortController();streamController.current=controller;
    setGenerating(true);setError('');setNotice('');setStream('');streamText.current='';
    try {
      const answer=await analyze({matterId:id,question:text.trim(),skillId},text=>{
        if(currentMatter.current!==id || controller.signal.aborted) return;
        streamText.current+=text;
        if(streamFrame.current===null) streamFrame.current=requestAnimationFrame(()=>{if(currentMatter.current===id&&!controller.signal.aborted)setStream(streamText.current);streamFrame.current=null;});
      },controller.signal);
      if(currentMatter.current===id && !controller.signal.aborted) {await refresh();if(currentMatter.current!==id||controller.signal.aborted)return;setSelectedAnswer(answer.id);setQuestion('');setStream('');setRailOpen(true);setRailTab('sources');}
    } catch(e) {if(!controller.signal.aborted) setError(e instanceof Error?e.message:'El análisis no pudo completarse.');}
    finally {if(streamController.current===controller) {setGenerating(false);streamController.current=null;}}
  }
  async function openWritten(answer:Answer) {await perform('open',async()=>{await api('answer.open',{matterId:answer.matterId,answerId:answer.id});setNotice('El escrito se abrió en la aplicación del equipo.');});}
  async function openOriginal(doc:DocumentRecord) {await perform('open',async()=>{await api('document.open',{matterId:doc.matterId,documentId:doc.id});setNotice('El documento se abrió en la aplicación del equipo.');});}
  async function exportAnswer(answer:Answer) {
    await perform('export',async()=>{downloadFile(await api<{name:string;base64:string;mime:string}>('answer.export',{answerId:answer.id,matterId:answer.matterId}));setNotice('El documento DOCX está listo para guardar.');});
  }
  const newMatterButton = <button className="primary" onClick={()=>setShowMatter(true)}><Plus size={16}/> Nuevo asunto</button>;
  const importInputRef = useRef<HTMLInputElement>(null);
  const importControl = <><button type="button" className="secondary" disabled={Boolean(busy)||!matterId} onClick={()=>importInputRef.current?.click()}><Upload size={15}/>{busy==='import'?'Importando…':'Importar documento'}</button><input ref={importInputRef} aria-label="Seleccionar documento" type="file" accept=".pdf,.docx,.txt,.md" hidden disabled={Boolean(busy)||!matterId} onChange={event=>{const file=event.target.files?.[0];if(file) void importFile(file);event.target.value='';}}/></>;

  const composer = <MetalPromptBar value={question} onChange={setQuestion} onSubmit={text=>{if(page==='home')setPage('workspace');void ask(text);}} onCancel={()=>{streamController.current?.abort();if(streamFrame.current!==null){cancelAnimationFrame(streamFrame.current);streamFrame.current=null;}streamText.current='';setGenerating(false);setStream('');}} matter={matter} documentCount={documents.length} engineReady={state==='ready'} busy={Boolean(busy)} generating={generating} skills={data.skills} skillId={skillId} onSkillChange={setSkillId} onAttach={selected=>void importFile(selected)} onPrepare={()=>setPage('settings')} selectionRef={promptSelection}/>;
  return <div className={`app-shell ${sidebarCollapsed?'sidebar-collapsed':''} macos-workspace`}>

    <aside className={`sidebar ${mobileNavOpen?'mobile-open':''}`} hidden={(sidebarCollapsed&&!mobileNavOpen)||!data.workspace}>
      <div className="brand"><span className="brand-mark" aria-hidden="true"><img src={lexMark} className="lex-brand-symbol theme-mark-light" alt=""/><img src={lexMarkDark} className="lex-brand-symbol theme-mark-dark" alt=""/></span><span>LEX <span className="brand-ai">AI</span></span><span className="pilot">Piloto</span></div>
      <div className="firm-name"><LockKeyhole size={13}/><span>{data.workspace?.name || 'Espacio jurídico privado'}</span></div>
      <nav aria-label="Navegación principal">{navigationGroups.map(group=>{const isOpen=openNavigationGroups[group.label];return <section className="nav-group" key={group.label}><button className="nav-group-toggle" aria-expanded={isOpen} aria-controls={`nav-group-${group.label}`} onClick={()=>setOpenNavigationGroups(previous=>({...previous,[group.label]:!previous[group.label]}))}><span>{group.label}</span><ChevronDown size={16}/></button><div id={`nav-group-${group.label}`} hidden={!isOpen}>{group.ids.map(id=>pages.find(item=>item.id===id)!).map(({id,label,icon:Icon})=>{const active=page===id||(id==='matters'&&page==='dossier');const count=id==='pending'&&pendingCount>0?pendingCount:undefined;return <button key={id} className={active?'nav-item active':'nav-item'} aria-current={active?'page':undefined} onClick={()=>navigateTo(id)}><Icon size={18}/><span>{label}</span>{count!==undefined&&<small className="nav-count">{count}</small>}</button>;})}</div></section>;})}</nav><button className="text-button tools-trigger" onClick={openCommands}><Search size={16}/> Buscar acciones <kbd>⌘ K</kbd></button>
      <div className="sidebar-bottom"><button className="appearance-quick-toggle" aria-label={`Cambiar apariencia: ${appearanceLabels[appearance]}`} title={`Apariencia: ${appearanceLabels[appearance]}`} onClick={()=>setAppearance(value=>value==='auto'?'light':value==='light'?'dark':'auto')}>{appearance==='auto'?<Monitor size={16}/>:appearance==='light'?<Sun size={16}/>:<Moon size={16}/>}<span>Apariencia</span><small>{appearanceLabels[appearance]}</small></button><button className="runtime-status" aria-label="Estado de LEX AI" title={assistantLabel} onClick={()=>setPage('settings')}><span className={`status-dot ${state==='ready'?'ready':state==='error'?'failed':''}`}/><span>{assistantLabel}<small>LEX AI · En este equipo</small></span><ChevronRight size={14}/></button><p><ShieldCheck size={12}/> Inferencia y archivos locales</p></div>
    </aside>
    <div className="app-content">
      <header className="context-bar">{data.workspace&&<button className="icon-button" aria-label={narrowViewport?(mobileNavOpen?'Cerrar menú':'Abrir menú'):(sidebarCollapsed?'Mostrar barra lateral':'Ocultar barra lateral')} aria-expanded={narrowViewport?mobileNavOpen:!sidebarCollapsed} onClick={()=>narrowViewport?setMobileNavOpen(value=>!value):setSidebarCollapsed(value=>!value)}>{narrowViewport?(mobileNavOpen?<PanelLeftClose size={18}/>:<PanelLeftOpen size={18}/>):sidebarCollapsed?<PanelLeftOpen size={18}/>:<PanelLeftClose size={18}/>}</button>}<div className="breadcrumb"><span>{data.workspace?.name || 'Bienvenido'}</span>{page==='dashboard'?<><ChevronRight size={13}/><strong>Panel</strong></>:matter && <><ChevronRight size={13}/><span>{matter.client}</span><ChevronRight size={13}/><strong>{matter.title}</strong></>}</div><div className="context-controls"><button className="command-trigger secondary" aria-label="Buscar y ejecutar acciones" onClick={openCommands}><Search size={15}/><span>Buscar</span><kbd>⌘ K</kbd></button>{page!=='dashboard'&&matter&&<button className="text-button dossier-trigger" onClick={()=>setPage('dossier')}>Expediente</button>}{page!=='dashboard'&&matter && <Badge>{jurisdictionLabel(matter.jurisdiction)}</Badge>}{page!=='dashboard'&&data.matters.length>0 && <select aria-label="Asunto activo" value={matterId} onChange={e=>chooseMatter(e.target.value)}>{data.matters.map(m=><option key={m.id} value={m.id}>{m.title}</option>)}</select>}</div></header>
      {error && <div className="banner error" role="alert"><CircleHelp size={17}/><span>{error}</span><button aria-label="Cerrar aviso" onClick={()=>setError('')}><X size={16}/></button></div>}
      {notice && <div className="banner success" role="status"><CheckCircle2 size={17}/><span>{notice}</span><button aria-label="Cerrar confirmación" onClick={()=>setNotice('')}><X size={16}/></button></div>}
      <main>
        {loading ? <Empty icon={LoaderCircle} title="Abriendo tu espacio local…"/> : !data.workspace ? <Onboarding busy={Boolean(busy)} onCreate={(name,practiceAreas)=>perform('workspace',async()=>{await api('workspace.create',{name,practiceAreas});await refresh();setPage('settings');})} onRetry={load} hasError={Boolean(error)}/> : <>
          {page==='dashboard'&&<Suspense fallback={<section className="page" aria-busy="true"><p role="status">Abriendo dashboard…</p></section>}><Dashboard data={data} scope={dashboardScope} onScopeChange={setDashboardScope} onCreateMatter={()=>setShowMatter(true)} onOpenMatter={id=>{if(data.matters.some(item=>item.id===id)){if(id!==matterId)chooseMatter(id);setPage('dossier');}}}/></Suspense>}
          {page==='home' && <section className="page assistant-home"><div className="home-welcome"><span className="home-lex">LEX</span><h1>¿En qué asunto trabajamos hoy?</h1><p>{matter?<>Tu contexto actual es <strong>{matter.title}</strong>.</>:'Crea un asunto para reunir documentos y comenzar una consulta.'}</p><button className="text-button" onClick={()=>setPage('dashboard')}><LayoutDashboard size={16}/> Ver dashboard</button></div>{matter?composer:<div className="home-create">{newMatterButton}<p>Un ámbito privado para los documentos de cada cliente.</p></div>}<MatterBento matter={matter} documents={documents} answers={answers} matters={data.matters} engine={engine} engineLabel={assistantLabel} onOpenMatter={()=>setPage('dossier')} onCreateMatter={()=>setShowMatter(true)} onBrowseMatters={()=>setPage('matters')} onDocuments={()=>setPage('documents')} onResearch={()=>setPage('research')} onSettings={()=>setPage('settings')} onOpenDocument={doc=>void openDocument(doc)} onOpenAnswer={answer=>{setSelectedAnswer(answer.id);setPage('workspace');}} onSelectMatter={selected=>{chooseMatter(selected.id);setPage('dossier');}}/><p className="home-local-note"><LockKeyhole size={13}/> Tus documentos y consultas se procesan en este equipo.</p></section>}

          {page==='matters' && <section className="page"><div className="page-heading"><div><h1>Asuntos</h1><p>Cada asunto delimita los documentos que puede consultar el asistente.</p></div>{newMatterButton}</div>{data.matters.length ? <div className="table-wrap"><table><thead><tr><th>Asunto</th><th>Cliente</th><th>Jurisdicción</th><th>Documentos</th><th><span className="sr-only">Acciones</span></th></tr></thead><tbody>{data.matters.map(m=><tr key={m.id}><td><strong>{m.title}</strong></td><td>{m.client}</td><td>{jurisdictionLabel(m.jurisdiction)}</td><td>{data.documents.filter(d=>d.matterId===m.id).length}</td><td><button className="text-button" onClick={()=>{chooseMatter(m.id);setPage('dossier');}}>Abrir <ChevronRight size={14}/></button></td></tr>)}</tbody></table></div>:<Empty title="Aún no hay asuntos">Organiza el trabajo por cliente, expediente o proyecto interno.</Empty>}</section>}

          {page==='documents' && (matter?<DocumentLibrary key={matter.id} matter={matter} documents={documents} importControl={importControl} onOpenOriginal={doc=>void openOriginal(doc)} onOpen={doc=>void openDocument(doc)} onAsk={askAboutDocument}/>:<section className="page"><h1>Documentos</h1><Empty title="Selecciona o crea un asunto" action={newMatterButton}>Los documentos se organizan dentro de un asunto.</Empty></section>)}
          {page==='pending' && (matter?<PendingView key={matter.id} matter={matter}/>:<section className="page"><h1>Pendientes</h1><Empty icon={CalendarDays} title="Selecciona o crea un asunto" action={newMatterButton}>Los pendientes se organizan dentro de un asunto.</Empty></section>)}
          {page==='agent-actions' && <AgentActionsView matter={matter} onRefresh={refresh}/>}
          {page==='conflicts' && <ConflictCheckView matter={matter} onRefresh={refresh}/>}
          {page==='checklist' && <ChecklistView matter={matter}/>}
          {page==='dossier'&&matter&&<MatterOverview tasks={data.tasks.filter(task=>task.matterId===matterId)} onTaskAction={async(action,payload)=>{await api(action,{...payload,matterId});await refresh();}} matter={matter} documents={documents} answers={answers} feedback={data.feedback.filter(item=>item.matterId===matterId)} onDocument={doc=>void openDocument(doc)} onAnswer={answer=>{setSelectedAnswer(answer.id);setPage('workspace');}} onAssistant={()=>setPage('workspace')}/>}
          {page==='training'&&<TrainingView/>}

          {page==='workspace' && (!matter ? <section className="page"><Empty icon={MessageSquare} title="Selecciona o crea un asunto para empezar" action={newMatterButton}>El asistente necesita un ámbito de trabajo antes de consultar documentos.</Empty></section> : <div className={`workspace-grid ${railOpen&&activeAnswer?'rail-open':''}`}><section className="analysis-pane"><div className="analysis-header"><div><h1>Asistente</h1><span className="muted small">{matter.title} · {jurisdictionLabel(matter.jurisdiction)}</span></div>{activeAnswer&&<button className="secondary rail-toggle" aria-label={railOpen?'Ocultar panel de contexto':'Mostrar panel de contexto'} aria-expanded={railOpen} aria-controls="context-panel" onClick={()=>setRailOpen(open=>!open)}><PanelRight size={16}/><span>Contexto</span></button>}</div><div className="analysis-scroll">{answers.length>1&&<label className="answer-history">Consultas guardadas<select value={activeAnswer?.id||''} onChange={e=>setSelectedAnswer(e.target.value)}>{answers.map((a,i)=><option key={a.id} value={a.id}>{a.question||`Análisis ${i+1}`}</option>)}</select></label>}{activeAnswer&&!generating?<AnswerView answer={activeAnswer} busy={Boolean(busy)} onCitation={showCitation} onOpen={()=>void openWritten(activeAnswer)} onExport={()=>void exportAnswer(activeAnswer)} onFeedback={(rating,comment)=>perform('feedback',async()=>{await api('feedback.create',{answerId:activeAnswer.id,matterId,rating,comment});await refresh();setNotice('Feedback guardado. No modifica automáticamente el comportamiento del asistente.');})}/>:!generating?<div className="assistant-empty"><div className="assistant-identity"><Avatar size="lg" decorative/><span className="home-lex">LEX</span></div><h2>Consulta el derecho.<br/>Trabaja en tu asunto.</h2><p>LEX AI recupera fuentes jurídicas locales para tu consulta. Añade documentos cuando quieras analizar los hechos de tu asunto.</p><div className="question-examples">{(documents.length?['¿Qué obligaciones asume cada parte?','¿Qué cláusulas requieren aclaración?','Resume los plazos y condiciones del contrato.']:['¿Qué establece el Código Civil Federal sobre el consentimiento en los contratos?','Localiza las disposiciones sobre el incumplimiento de obligaciones.','Explica la diferencia entre nulidad y rescisión con fuentes.']).map(text=><button key={text} onClick={()=>setQuestion(text)}>{text}<ChevronRight size={13}/></button>)}</div>{documents.length>0&&<div className="context-document-strip"><FileText size={15}/><span>{documents.length} documentos en el asunto</span><button className="text-button" onClick={()=>setPage('documents')}>Ver documentos</button></div>}</div>:<div className="generation-state" role="status"><div className="lex-generation-header"><AILoader size={56} text={stream?'Presentando':'Procesando'} decorative><Avatar size="sm" decorative/></AILoader><strong role="status">{stream?'Presentando el análisis…':'Procesando tu consulta localmente…'}</strong></div><p>La respuesta se muestra después de comprobar las referencias. Puede tardar varios minutos.</p>{stream&&<div className="reading-text" aria-live="off">{stream}</div>}</div>}</div><div className="workspace-composer">{composer}<p className="composer-disclaimer">LEX AI puede equivocarse. Revisa las fuentes y las conclusiones antes de utilizarlas.</p></div></section>{railOpen&&activeAnswer&&<aside className="evidence-rail" id="context-panel" role={compactRail?'dialog':undefined} aria-modal={compactRail?true:undefined} aria-label="Panel de contexto" onKeyDown={event=>{if(!compactRail||event.key!=='Tab')return;const controls=Array.from(event.currentTarget.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],select,input,[tabindex="0"]'));const first=controls[0],last=controls.at(-1);if(event.shiftKey&&(document.activeElement===first||!controls.includes(document.activeElement as HTMLElement))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}><div className="rail-header"><div className="rail-tabs" role="tablist" aria-label="Contenido del panel" onKeyDown={event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?'sources':event.key==='End'?'outputs':railTab==='sources'?'outputs':'sources';setRailTab(next);document.getElementById(`${next}-tab`)?.focus();}}><button id="sources-tab" role="tab" tabIndex={railTab==='sources'?0:-1} aria-selected={railTab==='sources'} aria-controls="sources-panel" onClick={()=>setRailTab('sources')}>Fuentes <span>{activeAnswer.citations.length}</span></button><button id="outputs-tab" role="tab" tabIndex={railTab==='outputs'?0:-1} aria-selected={railTab==='outputs'} aria-controls="outputs-panel" onClick={()=>setRailTab('outputs')}>Resultados</button></div><button className="icon-button" aria-label="Cerrar panel de contexto" onClick={()=>setRailOpen(false)}><X size={17}/></button></div>{<div hidden={railTab!=='sources'} className="rail-body" id="sources-panel" role="tabpanel" aria-labelledby="sources-tab"><p className="muted small">Pasajes recuperados para esta respuesta. Consulta la versión original antes de utilizarlos.</p>{activeAnswer.citations.map((source,i)=><OfficialSource key={`${source.id||source.sourceId}-${i}`} source={source}/>)}</div>}{<div hidden={railTab!=='outputs'} className="rail-body" id="outputs-panel" role="tabpanel" aria-labelledby="outputs-tab"><h2>Documento de esta respuesta</h2><div className="output-item"><FileText size={24}/><div><strong>Análisis del asunto</strong><small>Borrador para revisión profesional</small><button className="secondary" onClick={()=>void exportAnswer(activeAnswer)} disabled={Boolean(busy)}><Download size={14}/> Descargar DOCX</button></div></div><div className="rail-learning"><Library size={19}/><h3>Feedback y mejoras</h3><p>Las correcciones se conservan en Conocimiento. Ninguna propuesta se activa sin evaluación y aprobación.</p><button className="text-button" onClick={()=>setPage('knowledge')}>Abrir Conocimiento <ChevronRight size={13}/></button></div></div>}</aside>}</div>)}

          {page==='drafts'&&<section className="page drafts-page"><div className="page-heading"><div><h1>Escritos</h1><p>Borradores guardados del asunto activo. Revisa las fuentes antes de utilizarlos.</p></div></div>{answers.length?<div className="drafts-list">{[...answers].reverse().map(answer=><article key={answer.id} className="draft-row"><FileText size={22}/><div><button className="text-button" onClick={()=>{setSelectedAnswer(answer.id);setPage('workspace');}}>{answer.question||'Análisis del asunto'}</button><p>{matter?.title} · {dateLabel(answer.createdAt)}</p><small>Borrador para revisión profesional</small></div><div className="button-row"><button className="secondary" disabled={Boolean(busy)} onClick={()=>void openWritten(answer)}>Abrir escrito</button><button className="secondary" disabled={Boolean(busy)} onClick={()=>void exportAnswer(answer)}>Exportar DOCX</button></div></article>)}</div>:<Empty icon={FileText} title="Aún no hay escritos">Las respuestas guardadas del asistente aparecerán aquí para revisarlas y exportarlas.</Empty>}</section>}
          {page==='library'&&<PublicLibrary/>}
          {page==='sources'&&<SourcesView/>}
          {page==='research' && <Research sources={data.sources} jurisdiction={matter?.jurisdiction || 'MX-FED'} onError={setError}/>}
          {page==='skills' && <section className="page"><div className="page-heading"><div><h1>Habilidades jurídicas</h1><p>Capacidades delimitadas, con entradas, permisos y validaciones propias.</p></div></div><div className="skills-list">{data.skills.map(skill=><article className="skill-row" key={skill.id}><Sparkles size={23}/><div><h2>{skill.name}</h2><p>{skill.description}</p><small>Versión {skill.version || '1.0.0'} · Ejecución local</small></div><button className="secondary" onClick={()=>{setSkillId(skill.id);setPage('workspace');}}>Usar habilidad</button></article>)}</div><div className="scope-note"><ShieldCheck size={16}/> Las habilidades no pueden ejecutar órdenes del sistema ni realizar trámites oficiales.</div></section>}
          {page==='knowledge' && <Knowledge matters={data.matters} feedback={data.feedback} proposals={data.proposals} busy={Boolean(busy)} onAction={(action,payload)=>perform('proposal',async()=>{await api(action,payload);await refresh();setNotice('El registro de mejora se actualizó.');})}/>}
          {page==='settings' && <section className="page settings-page"><div className="page-heading"><div><h1>Configuración</h1><p>Asistente, privacidad y almacenamiento de este equipo.</p></div></div><section className="settings-section"><div><h2>Asistente LEX AI</h2><p>Versión de evaluación para notas y borradores breves: la calidad aún presenta limitaciones y requiere revisión profesional. LEX AI combina las instrucciones de la tarea, las fuentes y el contexto de tu asunto. Funciona en este equipo. La preparación inicial descarga los recursos del asistente; después, tus consultas y documentos se procesan localmente.</p></div><div className="engine-panel"><div className="engine-title"><span className={`status-dot ${state==='ready'?'ready':state==='error'?'failed':''}`}/><strong>{assistantLabel}</strong><Badge>LEX AI</Badge></div><p role="status">{assistantMessage}</p>{typeof engine.memoryWarning==='string'&&<p className="muted small" role="status">{engine.memoryWarning}</p>}{typeof engine.downloadBytes==='number'&&<p className="muted small">Descarga inicial: {new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}).format(engine.downloadBytes/1e9)} GB.{typeof engine.minMemoryGB==='number'?` Memoria mínima requerida: ${engine.minMemoryGB} GB.`:''}{engine.memoryMeasured===false?' Rendimiento en el equipo mínimo pendiente de medición.':''}</p>}{typeof engine.progress==='number' && engineBusy && <><progress value={engine.progress} max={100}/><small>{Math.round(engine.progress)} %</small></>}{engine.hardware && <p className="muted">{engine.hardware.platform} {engine.hardware.arch} · {engine.hardware.memoryGB || engine.hardware.totalMemoryGB || '—'} GB de RAM</p>}<div className="button-row"><button className="primary" disabled={Boolean(busy)||engineBusy||state==='ready'||engine.supported===false} onClick={()=>void perform('engine',async()=>{setEngine(await api<EngineStatus>('engine.initialize'));})}>{engineBusy?<LoaderCircle className="spin" size={15}/>:<Download size={15}/>} {state==='error'?'Reintentar preparación':'Preparar LEX AI'}</button><button className="secondary" disabled={Boolean(busy)||state==='stopped'} onClick={()=>void perform('engine',async()=>{setEngine(await api<EngineStatus>('engine.stop'));})}>Detener</button><button className="text-button" onClick={()=>void perform('engine',async()=>setEngine(await api<EngineStatus>('engine.status')))}>Actualizar estado</button></div></div></section><section className="settings-section"><div><h2>Privacidad del despacho</h2><p>Alcance de esta versión inicial.</p></div><dl className="settings-facts"><dt>Datos y respuestas</dt><dd>Almacenamiento local, sin envío a servicios externos de IA.</dd><dt>Acceso</dt><dd>Un despacho y un usuario del sistema operativo. No hay roles multiusuario en este piloto.</dd><dt>Fuentes jurídicas</dt><dd>Corpus oficial acotado con versión y procedencia. No es un servicio de actualización normativa.</dd><dt>Mejoras</dt><dd>Feedback y propuestas locales. Ninguna corrección cambia automáticamente el comportamiento de LEX AI.</dd><dt>Protección del dispositivo</dt><dd>La protección del disco y las copias de seguridad dependen de la configuración del equipo. Esta versión no incorpora cifrado propio de la base de datos.</dd></dl></section><section className="settings-section"><div><h2>Tu despacho</h2><p>{data.workspace.name}</p></div><div className="practice-chips">{data.workspace.practiceAreas.map(area=><Badge key={area}>{area}</Badge>)}</div></section><p className="version-line">LEX AI {appVersion} · Piloto supervisado · México</p></section>}
        </>}
      </main>
      {data.workspace && page==='settings' && <section className="page settings-appearance-portal appearance-settings"><div><h2>Apariencia</h2><p>Elige cómo se ve LEX AI en este equipo.</p></div><fieldset className="appearance-options"><legend className="sr-only">Apariencia</legend>{(['auto','light','dark'] as Appearance[]).map(option=>{const Icon=option==='auto'?Monitor:option==='light'?Sun:Moon;return <label key={option}><input type="radio" name="appearance" value={option} checked={appearance===option} onChange={()=>setAppearance(option)}/><Icon size={17}/><span>{appearanceLabels[option]}</span></label>;})}</fieldset></section>}
    </div>
    {showMatter && <Modal title="Nuevo asunto" onClose={()=>setShowMatter(false)}><MatterForm busy={Boolean(busy)} onSubmit={(title,client,jurisdiction)=>perform('matter',async()=>{const created=await api<Matter>('matter.create',{title,client,jurisdiction});await refresh();chooseMatter(created.id);setShowMatter(false);setPage('documents');})}/></Modal>}

    {commandOpen&&<CommandPalette items={commands} scope={matter?.title||'Sin asunto activo'} onClose={()=>setCommandOpen(false)}/>}
    {viewer && <Modal title={viewer.name} wide onClose={()=>setViewer(null)}><p className="scope-note"><FileText size={14}/> Texto extraído del documento. Su contenido no da instrucciones al asistente.</p><div className="document-review-grid"><div><DocumentText text={viewer.text} onExtract={excerpt=>{setQuestion(`Sobre el documento «${viewer.name}», considerando este extracto:\n\n> ${excerpt.slice(0,2800)}\n\nMi pregunta: `);setNotice('La búsqueda abarca todo el asunto activo; el extracto se incluye como contexto.');setViewer(null);setPage('workspace');requestAnimationFrame(()=>document.getElementById('question')?.focus());}}/></div><aside className="document-review-context"><h3>Contexto del asunto</h3><p>{matter?.title}</p><p className="muted small">Texto extraído para revisión. Las consultas pueden recuperar evidencia de todos los documentos del asunto.</p><button className="primary" onClick={()=>{setQuestion(`Sobre el documento «${viewer.name}»: `);setViewer(null);setPage('workspace');}}>Consultar documento</button>{activeAnswer&&<><h3>Último análisis guardado</h3><p>{activeAnswer.question}</p><div className="reading-text">{activeAnswer.text}</div>{activeAnswer.citations.map((source,index)=><OfficialSource key={index} source={source} compact/>)}</>}</aside></div></Modal>}
  </div>;
}

function Onboarding({busy,onCreate,onRetry,hasError}:{busy:boolean;onCreate:(name:string,areas:string[])=>Promise<void>;onRetry:()=>Promise<void>;hasError:boolean}) {
  const [name,setName]=useState('');const [areas,setAreas]=useState<string[]>(['Civil','Mercantil']);
  return <section className="onboarding onboarding-with-cover" aria-labelledby="onboarding-title"><AppCover/><div className="onboarding-content"><div className="onboarding-intro"><h1 id="onboarding-title">Un espacio privado para tu práctica jurídica.</h1><p>Reúne los documentos de cada asunto, encuentra sus fuentes y prepara borradores para revisión. Tu espacio de trabajo vive en este equipo.</p><ol className="app-cover-steps" aria-label="Preparación del espacio"><li aria-current="step"><span>1</span> Crear tu despacho</li><li><span>2</span> Preparar LEX AI</li><li><span>3</span> Abrir el primer asunto</li></ol></div><form className="onboarding-form" onSubmit={e=>{e.preventDefault();void onCreate(name.trim(),areas);}}><h2>Crea tu espacio de trabajo</h2><label htmlFor="firm-name">Nombre del despacho</label><input id="firm-name" autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="Nombre de tu despacho" required maxLength={120}/><fieldset><legend>Áreas de práctica</legend><p className="muted small">Selecciona las materias en las que trabaja tu equipo.</p><div className="practice-options">{practiceOptions.map(area=><label key={area}><input type="checkbox" checked={areas.includes(area)} onChange={()=>setAreas(previous=>previous.includes(area)?previous.filter(a=>a!==area):[...previous,area])}/>{area}</label>)}</div></fieldset><button className="primary" type="submit" disabled={busy||!name.trim()||!areas.length}>{busy?<LoaderCircle className="spin" size={16}/>:<Plus size={16}/>} Crear espacio privado</button><p className="privacy-caption">Este piloto guarda un solo despacho en este equipo. Usa documentos sintéticos durante la evaluación.</p>{hasError && <button type="button" className="text-button" onClick={()=>void onRetry()}>Reintentar conexión local</button>}</form></div></section>;
}
function Modal({title,onClose,children,wide=false}:{title:string;onClose:()=>void;children:ReactNode;wide?:boolean}) {
  const ref=useRef<HTMLDialogElement>(null);
  useEffect(()=>{ref.current?.showModal();return ()=>ref.current?.close();},[]);
  return <dialog className={`modal ${wide?'wide':''}`} ref={ref} onCancel={onClose}><div className="modal-heading"><h2>{title}</h2><button className="icon-button" aria-label="Cerrar diálogo" onClick={onClose}><X size={19}/></button></div>{children}</dialog>;
}
function MatterForm({busy,onSubmit}:{busy:boolean;onSubmit:(title:string,client:string,jurisdiction:string)=>Promise<void>}) {
  const [title,setTitle]=useState('');const [client,setClient]=useState('');const [jurisdiction,setJurisdiction]=useState('MX-CMX');
  return <form className="form-stack" onSubmit={e=>{e.preventDefault();void onSubmit(title.trim(),client.trim(),jurisdiction);}}><label htmlFor="matter-title">Nombre del asunto</label><input id="matter-title" value={title} onChange={e=>setTitle(e.target.value)} autoFocus required maxLength={200} placeholder="Revisión de contrato de servicios"/><label htmlFor="client">Cliente</label><input id="client" value={client} onChange={e=>setClient(e.target.value)} required maxLength={200} placeholder="Cliente de prueba"/><label htmlFor="jurisdiction">Jurisdicción de consulta</label><select id="jurisdiction" value={jurisdiction} onChange={e=>setJurisdiction(e.target.value)}><option value="MX-CMX">Ciudad de México</option><option value="MX-FED">Federal</option></select><p className="muted small">La jurisdicción delimita las fuentes recuperadas. Confirma su aplicabilidad al asunto.</p><button type="submit" className="primary" disabled={busy||!title.trim()||!client.trim()}><Plus size={16}/> Crear asunto</button></form>;
}
function AnswerView({answer,busy,onOpen,onExport,onFeedback,onCitation}:{answer:Answer;busy:boolean;onOpen:()=>void;onCitation:(id:string)=>void;onExport:()=>void;onFeedback:(rating:string,comment:string)=>Promise<void>}) {
  const [copied,setCopied]=useState(false);const [copyError,setCopyError]=useState('');const [open,setOpen]=useState(false);const [rating,setRating]=useState('accepted');const [comment,setComment]=useState('');
  useEffect(()=>{setOpen(false);setComment('');setRating('accepted');setCopied(false);setCopyError('');},[answer.id]);
  return <article className="answer"><div className="answer-question"><span>Tu consulta</span><p>{answer.question || 'Análisis del asunto'}</p></div><div className="answer-byline"><Avatar size="sm" decorative/><strong>LEX AI</strong><span>{dateLabel(answer.createdAt)}</span></div><div className="reading-text">{answer.text.split(/(\[[^\]\n]+\])/g).map((part,index)=>{const id=part.startsWith('[')?part.slice(1,-1):'';const position=answer.citations.findIndex(source=>(source.id || source.sourceId)===id);return position>=0?<button className="citation-link" key={index} aria-label={`Ver fuente ${position+1}: ${answer.citations[position].title || id}`} onClick={()=>onCitation(id)}>[{position+1}]</button>:part;})}</div><div className="grounding-note"><ShieldCheck size={16}/><p><strong>Referencias comprobadas contra los fragmentos.</strong> {answer.citations.some(source=>source.url)?`Fuentes consultadas: ${[...new Set(answer.citations.filter(source=>source.url).map(source=>dateLabel(source.retrievedAt)))].join(', ')}. `:''}No confirma vigencia actual ni sustituye la revisión profesional.</p></div><div className="answer-actions"><button className="secondary" onClick={onOpen} disabled={busy}><FileText size={15}/> Abrir escrito</button><button className="secondary" onClick={onExport} disabled={busy}><Download size={15}/> Exportar DOCX</button><button className="text-button" onClick={()=>setOpen(!open)}><MessageSquare size={15}/> Dar feedback</button><button className="text-button" onClick={async()=>{try{await navigator.clipboard.writeText(answer.text);setCopied(true);setCopyError('');}catch{setCopyError('No se pudo copiar. Selecciona el texto y usa Copiar.');}}}><Copy size={14}/>{copied?'Copiado':'Copiar'}</button></div>{copyError&&<p className="muted small" role="status">{copyError}</p>}{open && <form className="feedback-form" onSubmit={async e=>{e.preventDefault();await onFeedback(rating,comment);}}><label htmlFor="rating">¿Cómo evalúas esta respuesta?</label><select id="rating" value={rating} onChange={e=>setRating(e.target.value)}><option value="accepted">Aceptar</option><option value="rejected">Rechazar</option><option value="corrected">Corregir</option><option value="citation-error">Señalar una cita incorrecta</option></select><label htmlFor="feedback-comment">Corrección o comentario</label><textarea id="feedback-comment" rows={3} value={comment} onChange={e=>setComment(e.target.value)} maxLength={4000} required={rating!=='accepted'} placeholder="Explica qué debe conservarse, corregirse o verificarse."/><button className="primary" type="submit" disabled={busy||(rating!=='accepted'&&!comment.trim())}>Guardar feedback</button><small>Las propuestas de mejora se gestionan en Conocimiento y requieren aprobación.</small></form>}</article>;
}
function Research({sources,jurisdiction,onError}:{sources:Source[];jurisdiction:string;onError:(text:string)=>void}) {
  const [query,setQuery]=useState('');const [scope,setScope]=useState(jurisdiction);const [results,setResults]=useState<Source[]|null>(null);const [searching,setSearching]=useState(false);
  const visible=results || sources.filter(source=>source.jurisdiction===scope);
  return <section className="page research-page"><div className="page-heading"><div><h1>Investigación jurídica</h1><p>Consulta el corpus público local. Esta búsqueda no incluye documentos privados.</p></div><Badge tone="blue">Fuentes oficiales</Badge></div><form className="research-form" onSubmit={async e=>{e.preventDefault();setSearching(true);onError('');try{setResults(await api<Source[]>('research.search',{query,jurisdiction:scope}));}catch(error){onError(error instanceof Error?error.message:'No se pudo buscar.');}finally{setSearching(false);}}}><label className="sr-only" htmlFor="research-query">Buscar en fuentes oficiales</label><div className="search-input"><Search size={17}/><input id="research-query" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Busca un artículo, concepto u obligación" required/></div><select aria-label="Jurisdicción de las fuentes" value={scope} onChange={e=>{setScope(e.target.value);setResults(null);}}><option value="MX-FED">Federal</option><option value="MX-CMX">Ciudad de México</option></select><button className="primary" type="submit" disabled={searching||!query.trim()}>{searching?'Buscando…':'Buscar'}</button></form><div className="scope-note"><BookOpen size={15}/> Las fechas corresponden a las instantáneas consultadas. No se garantiza vigencia actual ni cobertura completa.</div><div className="section-heading"><h2>{results?'Resultados':'Fuentes disponibles'}</h2><span>{visible.length} fragmentos</span>{results && <button className="text-button" onClick={()=>{setResults(null);setQuery('');}}>Ver todo</button>}</div>{visible.length?<div className="research-results">{visible.map((source,i)=><OfficialSource key={source.id || i} source={source}/>)}</div>:<Empty icon={Search} title="No se encontraron fragmentos">Prueba otros términos o consulta directamente la fuente oficial. La falta de resultados no implica que no exista una disposición.</Empty>}</section>;
}
function Knowledge({matters,feedback,proposals,busy,onAction}:{matters:Matter[];feedback:Feedback[];proposals:Proposal[];busy:boolean;onAction:(action:string,payload:unknown)=>Promise<void>}) {
  const [reviewed,setReviewed]=useState<Record<string,boolean>>({});const [confirmation,setConfirmation]=useState<{proposalId:string;action:string}|null>(null);
  return <section className="page"><div className="page-heading"><div><h1>Conocimiento y mejora</h1><p>Convierte correcciones autorizadas en memoria del asunto, con evaluación y aprobación explícitas.</p></div></div><div className="scope-note"><ShieldCheck size={15}/> Guardar feedback no entrena al modelo. Las propuestas permanecen inactivas hasta su aprobación.</div><div className="knowledge-grid"><section><div className="section-heading"><h2>Propuestas de mejora</h2><span>{proposals.length}</span></div>{proposals.length?proposals.map(proposal=><article className="proposal" key={proposal.id}><div className="proposal-heading"><Badge tone={proposal.status==='active'?'green':'neutral'}>{proposalLabels[proposal.status] || proposal.status}</Badge><small>Versión {proposal.version || 1}</small></div><h3>Memoria del asunto</h3><p className="muted small">{matters.find(m=>m.id===proposal.matterId)?.title || 'Asunto de origen'}</p><p className="proposal-content">{proposal.content || proposal.text || proposal.candidate || 'Consulta el feedback de origen.'}</p>{proposal.evaluation && <details open><summary>Resultado de evaluación: {proposal.evaluation.passed?'comprobaciones superadas':'requiere corrección'}</summary><ul className="evaluation-checks">{Object.entries((proposal.evaluation.checks || {}) as Record<string,boolean>).map(([name,passed])=><li key={name}>{passed?<CheckCircle2 size={13}/>:<CircleHelp size={13}/>}<span>{{scope:'La nota pertenece al asunto de origen',traceability:'La propuesta conserva la corrección registrada',boundedNote:'La nota respeta los límites permitidos',citationBaseline:'El análisis de origen tiene citas comprobadas'}[name] || name}: {passed?'correcto':'requiere revisión'}</span></li>)}</ul><p className="muted small">Comprobaciones estructurales. La corrección jurídica, los efectos sobre otras respuestas y la utilidad requieren revisión profesional.</p></details>}{proposal.status==='proposed' && <><div className="button-row"><button className="secondary" disabled={busy} onClick={()=>void onAction('proposal.evaluate',{proposalId:proposal.id})}>Evaluar propuesta</button></div><label className="review-checkbox"><input type="checkbox" checked={Boolean(reviewed[proposal.id])} onChange={e=>setReviewed(previous=>({...previous,[proposal.id]:e.target.checked}))}/> He revisado la propuesta y su alcance para este asunto.</label><button className="primary" disabled={busy||proposal.evaluation?.passed!==true||!reviewed[proposal.id]} onClick={()=>setConfirmation({proposalId:proposal.id,action:'proposal.approve'})}>Aprobar y activar</button>{proposal.evaluation?.passed!==true && <small className="muted">Primero debe superar la evaluación estructural. Esta no sustituye la revisión jurídica.</small>}</>}{proposal.history && <details className="version-history"><summary>Historial de cambios</summary><ol>{proposal.history.map((entry,index)=><li key={index}>{{proposed:'Propuesta creada',evaluated:'Evaluación registrada',approved:'Aprobada',superseded:'Sustituida',restored:'Restaurada','rolled-back':'Revertida'}[entry.event] || entry.event} · {dateLabel(entry.at)}</li>)}</ol></details>}{proposal.status==='active' && <button className="secondary" disabled={busy} onClick={()=>setConfirmation({proposalId:proposal.id,action:'proposal.rollback'})}>Revertir esta versión</button>}</article>):<Empty icon={Library} title="Sin propuestas todavía">Crea una propuesta a partir de una corrección guardada. Su alcance se limita al asunto de origen.</Empty>}</section><aside><div className="section-heading"><h2>Feedback registrado</h2><span>{feedback.length}</span></div>{feedback.length?feedback.slice().reverse().map(item=><article className="feedback-record" key={item.id}><Badge>{feedbackLabels[item.rating] || item.rating}</Badge><small className="feedback-matter">{matters.find(m=>m.id===item.matterId)?.title}</small><p>{item.comment || 'Respuesta aceptada sin comentarios.'}</p><small>{dateLabel(item.createdAt)}</small>{['corrected','citation-error','rejected'].includes(item.rating) && item.comment && <button className="text-button" disabled={busy||proposals.some(p=>p.feedbackId===item.id)} onClick={()=>void onAction('proposal.create',{feedbackId:item.id})}>{proposals.some(p=>p.feedbackId===item.id)?'Propuesta creada':'Crear propuesta inactiva'}</button>}</article>):<p className="muted">El feedback de los análisis aparecerá aquí.</p>}</aside></div>{confirmation && <Modal title={confirmation.action==='proposal.approve'?'Aprobar cambio de memoria':'Revertir cambio de memoria'} onClose={()=>setConfirmation(null)}><p>Esta acción modifica la memoria aprobada del asunto de origen. No modifica documentos ni entrena al modelo.</p><div className="button-row"><button className="secondary" onClick={()=>setConfirmation(null)}>Cancelar</button><button className="primary" disabled={busy} onClick={async()=>{await onAction(confirmation.action,{proposalId:confirmation.proposalId,reviewConfirmed:true});setConfirmation(null);}}>Confirmar {confirmation.action==='proposal.approve'?'aprobación':'reversión'}</button></div></Modal>}</section>;
}
